    newViewers:'New viewers', casual:'Casual viewers', regular:'Regular viewers', returning:'Returning viewers',
    avgViewsPerViewer:'Average views/viewer', qualifiedLeads:'Qualified leads', bookings:'Bookings', sales:'Sales', revenue:'Revenue'
