  const ratio = (a,b) => (num(a)!==null && num(b)!==null && num(b)!==0) ? num(a)/num(b) : null;
  const signed = v => v===null||!Number.isFinite(v) ? '—' : `${v>=0?'+':''}${(v*100).toFixed(1)}%`;
  const median = xs => { const a=xs.map(num).filter(v=>v!==null).sort((a,b)=>a-b); if(!a.length)return null; const m=Math.floor(a.length/2); return a.length%2?a[m]:(a[m-1]+a[m])/2; };
  const today = () => { const d=new Date(),p=x=>String(x).padStart(2,'0'); return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`; };
  const uid = p => `${p}_${Math.random().toString(36).slice(2,9)}`;

