    c.coachOS = c.coachOS && typeof c.coachOS==='object' ? c.coachOS : {};
    const s=c.coachOS;
    s.version='v185.2';
    s.baseline=s.baseline&&typeof s.baseline==='object'?s.baseline:{};
    s.baseline.context=s.baseline.context&&typeof s.baseline.context==='object'?s.baseline.context:{};
    s.baseline.current90=s.baseline.current90&&typeof s.baseline.current90==='object'?s.baseline.current90:{};
