    s.analytics=s.analytics&&typeof s.analytics==='object'?s.analytics:{};
    if(!Array.isArray(s.analytics.snapshots))s.analytics.snapshots=[];
    if(!Array.isArray(s.analytics.eras))s.analytics.eras=[];
