  function baselineCoreStatus(c){
    const s=ensure(c),b=s.baseline,ctx=b.context||{},cur=b.current90||{},pri=b.prior90||{},m=primary7dBaseline(c)||{},st=b.strengths||{};
    const groups=[
      ['Context',!!ctx.eraStart && !!ctx.channelGoal && !!ctx.desiredAudience],
      ['90-day comparison',num(cur.views)!==null && num(pri.views)!==null && (num(cur.impressions)!==null||num(cur.newViewers)!==null)],
      ['Matched 7-day normal',m.confirmedComparable===true && num(m.views)!==null && num(m.impressions)!==null && num(m.ctr)!==null && num(m.ret30)!==null && num(m.n)>=3],
      ['Content strengths',!!st.topTopic && !!st.topFormat],
      ['Research context',!!st.audienceWatches || !!st.resurrection || !!st.failedSibling]
    ];
    const businessRelevant=!!String(ctx.businessGoal||'').trim() || /lead|book|sale|revenue|convert|business/i.test(String(ctx.channelGoal||''));
    if(businessRelevant)groups.push(['Business starting point',num(cur.qualifiedLeads)!==null||num(cur.bookings)!==null||num(cur.sales)!==null||num(cur.revenue)!==null]);
    const core=groups.slice(0,3),enrichment=groups.slice(3);
    return {groups,core,enrichment,done:groups.filter(x=>x[1]).length,coreDone:core.filter(x=>x[1]).length,ready:core.every(x=>x[1]),complete:groups.every(x=>x[1]),businessRelevant};
  }

  function dueReview(c){
    const now=Date.now(),era=ensure(c)?.baseline?.context?.eraStart||'';
    const defs=[['_28d',28*86400000],['_7d',7*86400000],['_48h',48*3600000]];
    const rows=[];
    (c?.videos||[]).forEach(v=>{
      const pd=v?.cta?.publishDate||v?.publishDate||''; if(!pd||(era&&pd<era))return;
      const t=new Date(pd+'T12:00:00').getTime(); if(!Number.isFinite(t)||t>now)return;
      const vo=ensureVideo(v),reviews=vo.reviews||{};
      for(const [win,ms] of defs){ if(now-t>=ms){
        const laterDone = defs.slice(0,defs.findIndex(x=>x[0]===win)).some(([w])=>reviews[w]?.savedAt);
        if(!laterDone && !reviews[win]?.savedAt){ rows.push({v,win,due:t+ms}); }
        break;
      }}
    });
    return rows.sort((a,b)=>a.due-b.due)[0]||null;
  }

  function appState(){ try{return typeof state==='object'&&state?state:null}catch(_){return null} }
