  function upsertAnalyticsPulse(c,pulse){
    const a=analyticsState(c),x={...(pulse||{})};
    if(!x.id)x.id=uid('snap');
    const same=a.snapshots.findIndex(y=>y && y.date===x.date && y.period===x.period);
    if(same>=0){
      const prev=a.snapshots[same]||{},merged={...prev};
      Object.entries(x).forEach(([k,v])=>{if(v!==''&&v!==null&&v!==undefined)merged[k]=v;});
      const sources=[prev.source,x.source].filter(Boolean).flatMap(v=>String(v).split(' + ')).filter((v,i,a)=>a.indexOf(v)===i);
      if(sources.length)merged.source=sources.join(' + ');
      merged.id=prev.id||x.id;
      a.snapshots[same]=merged;
      return merged;
    }
    a.snapshots.unshift(x);
    return x;
  }
