  function saveAnalyticsFocus(){const c=cNow(),s=ensure(c),d=analyticsDiagnosis(c);if(d.leading==='Not enough evidence yet'){toastNow('Collect the missing evidence before selecting a focus');return;}s.analytics.currentFocus={leading:d.leading,confidence:d.confidence,why:d.why,alternative:d.alternative,check:d.check,focus:d.focus,savedAt:today()};s.analytics.focusHistory.unshift({...s.analytics.currentFocus,id:uid('focus')});s.diagnosis={...(s.diagnosis||{}),leading:d.leading,confidence:d.confidence,because:d.why.join('\n'),alternative:d.alternative,checkNext:d.check,decision:d.focus,savedAt:today()};c.currentConstraint=d.leading;saveNow();toastNow('Current analytics focus saved');analyticsHome();}
  function newEraForm(){const c=cNow(),s=ensure(c),latest=latestSnapshot(c,'90d');const body=`<div class="cg-section"><div class="cg-kicker">New Strategy Period</div><h3>Only reset the starting line when the channel materially changed</h3><p>Use this after the channel meaningfully changes, such as a new audience, host, format, positioning, production style, or strategy. Old evidence is archived, not deleted.</p><div class="cg-fields">${field('cg-era-new-date','New strategy period begins',today(),'','date')}${area('cg-era-reason','Why this is a new strategy period','','What changed enough that the old numbers no longer represent the channel?')}<label class="cg-confirm"><input id="cg-era-confirm" type="checkbox"> I understand this archives current baselines and requires rebuilding similar video normals.</label></div><p class="cg-note">Latest 90-day update available: ${esc(latest?.date||'none')} · ${fmt(latest?.views)} views · ${pct(latest?.ctr)} CTR.</p></div>`;openGuide('Start New Strategy Period',body,`${btn('analytics','Cancel')} ${btn('analytics-new-era-save','Start new era','dark')}`);}
  function saveNewEra(){const c=cNow(),s=ensure(c),a=s.analytics;if(!document.getElementById('cg-era-confirm')?.checked){toastNow('Confirm the new strategy reset first');return;}const latest=latestSnapshot(c,'90d');if(!latest){toastNow('Add a 90-day snapshot first');return;}a.eras.unshift({id:uid('era'),endedAt:val('cg-era-new-date')||today(),reason:val('cg-era-reason'),baseline:cloneSafe(s.baseline),plan90:cloneSafe(s.plan90),diagnosis:cloneSafe(s.diagnosis),focus:s.analytics.currentFocus||null});s.baseline.context={...(s.baseline.context||{}),eraStart:val('cg-era-new-date')||today(),baselineDate:latest.date||val('cg-era-new-date')||today()};s.baseline.prior90={};s.baseline.current90={...latest};delete s.baseline.current90.id;delete s.baseline.current90.period;delete s.baseline.current90.label;delete s.baseline.current90.date;delete s.baseline.current90.savedAt;s.baseline.sets.forEach(x=>x.archived=true);s.baseline.matched={};s.diagnosis={};s.plan90={};saveNow();toastNow('New strategy period started. Rebuild matched baselines.');baselineSummary();}
  function analyticsReportBlock(c){
    const x=analyticsDigest(c),d=x.d,p=x.pprog,s=ensure(c),m=primary7dBaseline(c)||{},hist=m.id?baselineHistoryFor(c,m):[],first=hist[0]||null,refresh=baselineRefreshStatus(c,m);
    const baselineLine=m.id||m.confirmedComparable?`${m.name||'Primary 7-day baseline'} · v${m.version||1} · ${m.n||'—'} videos · ${m.refreshedAt||m.savedAt||'undated'}`:'Not established';
    const baselineChange=first?`7d views ${baselineDeltaText(m,first,'views')}; impressions ${baselineDeltaText(m,first,'impressions')}; CTR ${baselineDeltaText(m,first,'ctr',true)}; 0:30 ${baselineDeltaText(m,first,'ret30',true)} vs first saved normal`:'No approved normal update yet';
    return `\n## Analytics Summary\n- Permanent starting line: ${x.start.date||'Not dated'}\n- Latest channel update: ${x.cur.date||'Not dated'}\n- Period comparison: ${M.periodNote(x.cur,previousSnapshot(c,'90d'))}\n- Calculation version: ${M.VERSION}\n- What this creator usually gets: ${baselineLine}\n- Current normal change: ${baselineChange}\n- Current normal update status: ${refresh.label}\n- Current main problem: ${d.leading} (${d.confidence})\n- Metrics supporting diagnosis: ${diagnosisMetricSummary(c,d)}\n- Current focus: ${d.focus}\n- Biggest alternative: ${d.alternative}\n- Check next: ${d.check}\n- 90-day plan status: ${p.status} — ${p.detail}\n- Strongest topic clue: ${x.topTopic?`${x.topTopic.name} · ${x.topTopic.median.toFixed(2)}× · n=${x.topTopic.n}`:'Not enough matched evidence'}\n- Strongest format clue: ${x.topFormat?`${x.topFormat.name} · ${x.topFormat.median.toFixed(2)}× · n=${x.topFormat.n}`:'Not enough matched evidence'}\n- Reviewed evidence: ${s.learnings.filter(l=>l.evidence).map(l=>`${l.video||l.videoId} · ${l.window} · baseline ${l.evidence.baselineId||'provisional'} v${l.evidence.baselineVersion||'—'} · ${l.evidence.observation?.sourceRef||'source not recorded'}`).join(' | ')||'Legacy learnings have no frozen source packet'}\n- Known Truths: ${s.knownTruths.slice(0,3).map(t=>t.statement||t.text).filter(Boolean).join(' | ')||'None promoted yet'}\n`+(window.AcceleratorDecisions?.events(c).length?'\n## Accepted experiments and outcomes\n'+window.AcceleratorDecisions.handoff(c):'');
  }

  function contextualStrip(){
    const c=cNow(); if(!c)return; if(window.__cgNativeView==='analytics'){document.getElementById('cg-context-strip')?.remove();return;} let view='';try{view=state?.view||''}catch(_){}
    const page=document.querySelector('main .page,.page'); if(!page)return;
    let el=document.getElementById('cg-context-strip');
    if(!['strategy','plan','videos','planner','learn'].includes(view)){if(el)el.remove();return;}
    const s=ensure(c),bs=baselineCoreStatus(c),due=dueReview(c),m=primary7dBaseline(c)||{},refresh=baselineRefreshStatus(c,m); let action='home',title='Coach next step',text='Open the guided coaching workflow.',extra='';
    if(view==='strategy'){
      if(!bs.ready){action='baseline:1';title='Measurement setup needed';text='Capture the fixed starting line and a fair current-strategy 7-day normal before prescribing strategy.';extra=btn('baseline:1','Set up baseline','dark');}
      else if(!s.diagnosis?.savedAt){action='diagnosis';title='Ready to diagnose';text=`Current normal: ${fmt(m.views)} 7d views · ${pct(m.ctr)} CTR · ${pct(m.ret30)} at 0:30 · ${m.n||'—'} similar videos. ${refresh.label}.`;extra=`${btn('baseline:summary','Baseline')} ${btn('diagnosis','Diagnose','dark')}`;}
      else{action='diagnosis';title=`Current diagnosis: ${s.diagnosis.leading||'Review diagnosis'}`;text=`Evidence is interpreted against ${m.name||'the current 7-day baseline'} · v${m.version||1}. ${refresh.label}. Build the 90-day plan from this diagnosis, not from raw metrics alone.`;extra=`${btn('baseline:summary','Baseline')} ${btn('diagnosis','Diagnosis','dark')}`;}
    }
    if(view==='plan'){action='plan90';title=s.plan90?.savedAt?'90-day plan is active':'Build the 90-day plan from the diagnosis';text='Protect a proven strength, improve one main problem, define the main metric, what needs to stay healthy, and when to keep, change, or stop.';extra=btn('plan90',s.plan90?.savedAt?'Open plan':'Build plan','dark');}
    if(view==='videos'||view==='planner'){action='video-prep';title='Plan this video';text='Use the strongest data and examples you have. Give the video one job, one question you want it to answer, and one fair comparison.';extra=btn('video-prep','Open video strategy','dark');}
    if(view==='learn'){
      if(due){action=`review:${due.win}:${due.v.id}`;title=`${WIN_LABEL[due.win]} review due`;text=`Review ${due.v.package?.finalTitle||due.v.title||'the due video'} with the same OUTCOME → SHOW → CLICK → WATCH → RETURN → RESULT logic.`;extra=btn(action,'Open review','dark');}
      else{action='review-picker';title='Turn the result into a useful lesson';text='Review the right checkpoint, compare it with what this creator usually got at that point, then write down what it means and what should change next.';extra=btn('review-picker','Review video','dark');}
    }
    if(!el){el=document.createElement('div');el.id='cg-context-strip';page.prepend(el);}
    const html=`<div><b>${esc(title)}</b><span>${esc(text)}</span></div><div class="actions">${extra||btn(action,'Open','dark')}</div>`;
    if(el.innerHTML!==html)el.innerHTML=html;
  }

  function normalizeTopbarLayout(){
    const bar=document.querySelector('.topbar');if(!bar)return;
    const nav=bar.querySelector(':scope > .v11-primary-nav,:scope > .nav');
    const brand=bar.querySelector(':scope > .brand');
    let controls=document.getElementById('cg-topbar-controls');
    if(!controls){controls=document.createElement('div');controls.id='cg-topbar-controls';controls.className='cg-topbar-controls';bar.appendChild(controls);}
    [...bar.children].forEach(el=>{if(el!==brand&&el!==nav&&el!==controls)controls.appendChild(el);});
  }
