    if(a==='analytics'){window.__analyticsMissingFlow=false;return analyticsHome();} if(a==='analytics-snapshot-new')return analyticsSnapshot('new'); if(a.startsWith('analytics-snapshot-edit:'))return analyticsSnapshot(a.split(':')[1]); if(a==='analytics-snapshot-save')return saveAnalyticsSnapshot(); if(a==='analytics-audience-new')return analyticsAudienceSnapshot('new'); if(a.startsWith('analytics-audience-edit:'))return analyticsAudienceSnapshot(a.slice('analytics-audience-edit:'.length)); if(a==='analytics-audience-save')return saveAnalyticsAudienceSnapshot(); if(a==='analytics-history')return analyticsHistory(); if(a==='analytics-save-focus')return saveAnalyticsFocus(); if(a==='analytics-new-era')return newEraForm(); if(a==='analytics-new-era-save')return saveNewEra(); if(a==='analytics-accuracy')return diagnosisAccuracy(); if(a==='analytics-accuracy-new')return diagnosisAccuracyForm(); if(a==='analytics-accuracy-save')return saveDiagnosisAccuracy(); if(a==='analytics-truths')return knownTruths(); if(a==='analytics-truth-new')return knownTruthForm(); if(a==='analytics-truth-save')return saveKnownTruth();
    if(a.startsWith('baseline:')){const x=a.split(':')[1];return x==='summary'?baselineSummary():baseline(Number(x)||1)}
    if(a.startsWith('baseline-save:'))return saveBaselineStep(Number(a.split(':')[1]));
    if(a==='baseline-auto')return autoBaseline(); if(a==='saved-reports-save')return saveSavedReports();
