    if(a==='baseline-new')return baselineBuilder('new'); if(a.startsWith('baseline-set:'))return baselineBuilder(a.split(':')[1]); if(a==='baseline-set-auto')return prefillBaselineSet(); if(a==='baseline-set-save')return saveBaselineSet(); if(a.startsWith('baseline-set-primary:'))return makePrimaryBaseline(a.split(':')[1]); if(a.startsWith('baseline-set-delete:'))return deleteBaselineSet(a.split(':')[1]);
